sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
	if (isLoading || newValue === '') {
		return;
	}

	var currentState = g_form.getValue('state');

	if (currentState === '') return;

	var ga = new GlideAjax("x_1590365_worksp_0.WorkspacePlanningUtils");
	ga.addParam("sysparm_name", "validateSameCityAndState");
	ga.addParam("sysparm_base_city", newValue);
	ga.addParam("sysparm_base_state", currentState);

	ga.getXMLAnswer(function (response) {
		if (!response) return;

		var objResponse = JSON.parse(response);
		var infoMsg = objResponse.message;

		if (infoMsg) {
			g_form.clearValue('city');
			g_form.showFieldMsg('city', infoMsg, 'error');
		} else {
			return;
		}
	});
}
